def _is_setuptools_namespace(location: pathlib.Path) -> bool:
    try:
        with open(location / "__init__.py", "rb") as stream:
            data = stream.read(2048)
    except OSError:
        return True
    extend_path = b"pkgutil" not in data or b"extend_path" in data
    declare_namespace = (
        b"pkg_resources" in data and b"declare_namespace(__name__)" not in data
    )
    return extend_path and declare_namespace


